36		fmt.Println("  normalize   read newline-delimited JSON logs from stdin and write")
37		fmt.Println("              normalized event results to stdout, one JSON object per line;")
38		fmt.Println("              exits non-zero when one or more input lines fail")
39		fmt.Println("  version     print the relayproof version")
40		fmt.Println("  help        show this help")
41	}
