45		if err != nil {
46			fmt.Fprintf(os.Stderr, "normalize: %v\n", err)
47			os.Exit(2)
48		}
49		if failures > 0 {
50			os.Exit(1)
51		}
52	}
53	
54	func runDemo() {
55		headers := map[string]relayproof.Header{
56			"chain-a": {Chain: "chain-a", Height: 1024, Root: "0xabc", Trusted: true},
57		}
58		consumed := map[string]bool{}
59		messages := []relayproof.Message{
60			{ID: "msg-1", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 1000},
61			{ID: "msg-2", From: "chain-c", To: "chain-b", Nonce: 1, ProofAt: 10},
62		}
63		for _, message := range messages {
64			delivery := relayproof.Verify(headers, message, consumed)
65			fmt.Printf("message=%s status=%s reason=%s\n", delivery.Message, delivery.Status, delivery.Reason)
66		}
67		replay := relayproof.Verify(headers, messages[0], consumed)
68		fmt.Printf("replay of %s status=%s reason=%s\n", replay.Message, replay.Status, replay.Reason)
69		fmt.Println("pending:", relayproof.Pending(headers, messages))
70	}
