13	func runNormalize(t *testing.T, input string) []map[string]any {
14		t.Helper()
15		var out bytes.Buffer
16		failures, err := NormalizeReader(strings.NewReader(input), &out)
17		if err != nil {
18			t.Fatalf("NormalizeReader returned error: %v", err)
19		}
20		results := []map[string]any{}
21		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
22		for {
23			var m map[string]any
24			if err := dec.Decode(&m); err != nil {
25				if err == io.EOF {
26					break
27				}
28				t.Fatalf("decoding result: %v", err)
29			}
30			results = append(results, m)
31		}
32		if got := countFailures(results); got != failures {
33			t.Fatalf("NormalizeReader returned %d failures but output shows %d", failures, got)
34		}
35		return results
36	}
