package relayproof

import (
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// Regression coverage for duplicate top-level field detection. Duplicates
// are judged by the JSON-decoded field name, so escaped spellings such as
// "action" are the same key as "action"; the rule applies equally to
// canonical names, aliases, and unknown fields (including non-ASCII ones).
// The check is structural and runs before field validation: equal values
// still fail, differing values are still reported as duplicates (never as a
// value conflict or as the later value winning), and a mistyped second
// occurrence does not turn the error into a type error.

const dupRegTimestamp = "2026-01-02T00:00:00Z"

func TestNormalizeDuplicateTopLevelKeysUseDecodedName(t *testing.T) {
	cases := []struct {
		name  string
		input string
		// field is the decoded key name that must be identifiable in the
		// error message regardless of which spelling carried the escape.
		field string
	}{
		{
			name:  "canonical action: plain then escaped, equal values",
			input: `{"timestamp":"` + dupRegTimestamp + `","action":"a","action":"a"}`,
			field: FieldAction,
		},
		{
			name:  "canonical action: escaped then plain, equal values",
			input: `{"timestamp":"` + dupRegTimestamp + `","action":"a","action":"a"}`,
			field: FieldAction,
		},
		{
