		{
			name:  "canonical source_ip: plain duplicates escaped, equal values",
			input: `{"timestamp":"` + dupRegTimestamp + `","action":"a","source_ip":"127.0.0.1","source_ip":"127.0.0.1"}`,
			field: FieldSourceIP,
		},
		{
			name:  "alias time: plain duplicates escaped, equal values",
			input: `{"time":"` + dupRegTimestamp + `","time":"` + dupRegTimestamp + `","action":"a"}`,
			field: "time",
		},
		{
			name:  "alias event_type: escaped duplicates plain, different values",
			input: `{"timestamp":"` + dupRegTimestamp + `","event_type":"a","event_type":"b"}`,
			field: "event_type",
		},
		{
			name:  "alias src_ip: plain duplicates escaped",
			input: `{"timestamp":"` + dupRegTimestamp + `","action":"a","src_ip":"127.0.0.1","src_ip":"127.0.0.1"}`,
