				t.Fatalf("error must name the decoded field %q, got %q", tc.field, msg)
			}
			if strings.Contains(strings.ToLower(msg), "conflict") {
				t.Fatalf("duplicate keys must not be reported as a value conflict: %q", msg)
			}
		})
	}
}

